+		return nil, err
+	}
+	return &Stanza{
+		Type: "ssh-ed25519",
+		Args: []string{
+			r.tag,
+			base64.RawStdEncoding.EncodeToString(eph.PublicKey().Bytes()),
+		},
+		Body: body,
+	}, nil
