package main

import (
	"bytes"
	"crypto/ecdh"
	"crypto/ed25519"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"encoding/pem"
	"errors"
	"fmt"
	"math/big"
	"strings"
)

type parsedSSHPublic struct {
	algo    string
	wire    []byte
	ed25519 ed25519.PublicKey
	rsa     *rsa.PublicKey
}

type sshReader struct {
	data []byte
}

func parseSSHRecipient(recipient string) (Recipient, error) {
	pub, err := parseAuthorizedKeyLine(recipient)
	if err != nil {
		return nil, err
	}
	tag := sshKeyTag(pub.wire)
	switch pub.algo {
	case "ssh-ed25519":
		curvePub, err := ed25519PublicToCurve25519(pub.ed25519)
		if err != nil {
			return nil, err
		}
		return &SSHEd25519Recipient{
			tag:         tag,
			publicWire:  pub.wire,
			publicCurve: curvePub,
		}, nil
	case "ssh-rsa":
		if pub.rsa == nil || pub.rsa.N.BitLen() < 2048 {
			return nil, errors.New("unsupported ssh recipient")
		}
		return &SSHRSARecipient{tag: tag, key: pub.rsa}, nil
	default:
		return nil, errors.New("unsupported ssh recipient")
	}
}

func parseSSHIdentity(data []byte) (Identity, error) {
	block, _ := pem.Decode(data)
	if block == nil {
		return nil, errors.New("unsupported ssh identity")
	}
	switch block.Type {
	case "OPENSSH PRIVATE KEY":
		return parseOpenSSHPrivateKey(block.Bytes)
	case "RSA PRIVATE KEY":
		key, err := x509.ParsePKCS1PrivateKey(block.Bytes)
		if err != nil {
			return nil, err
		}
		return &SSHRSAIdentity{
			tag: sshKeyTag(marshalRSAPublicKey(&key.PublicKey)),
			key: key,
		}, nil
	case "PRIVATE KEY":
		key, err := x509.ParsePKCS8PrivateKey(block.Bytes)
		if err != nil {
			return nil, err
		}
		switch k := key.(type) {
		case *rsa.PrivateKey:
			return &SSHRSAIdentity{
				tag: sshKeyTag(marshalRSAPublicKey(&k.PublicKey)),
				key: k,
			}, nil
		case ed25519.PrivateKey:
			pub := k.Public().(ed25519.PublicKey)
			wire := marshalEd25519PublicKey(pub)
			curvePub, err := ed25519PublicToCurve25519(pub)
			if err != nil {
				return nil, err
			}
			return &SSHEd25519Identity{
				tag:         sshKeyTag(wire),
				privateKey:  ed25519SeedToCurve25519(k.Seed()),
				publicCurve: curvePub,
				publicWire:  wire,
			}, nil
		default:
			return nil, errors.New("unsupported ssh identity")
		}
	default:
		return nil, errors.New("unsupported ssh identity")
	}
}

func parseOpenSSHPrivateKey(block []byte) (Identity, error) {
	const magic = "openssh-key-v1\x00"
	if !bytes.HasPrefix(block, []byte(magic)) {
		return nil, errors.New("unsupported ssh identity")
	}

	r := sshReader{data: block[len(magic):]}
	cipherName, err := r.readString()
	if err != nil {
		return nil, err
	}
	kdfName, err := r.readString()
	if err != nil {
		return nil, err
	}
	if _, err := r.readString(); err != nil {
		return nil, err
	}
	nkeys, err := r.readUint32()
	if err != nil {
		return nil, err
	}
	if string(cipherName) != "none" || string(kdfName) != "none" {
		return nil, errors.New("unsupported encrypted ssh identity")
	}
	if nkeys != 1 {
		return nil, errors.New("unsupported ssh identity")
	}
	pubWire, err := r.readString()
	if err != nil {
		return nil, err
	}
	privateBlock, err := r.readString()
	if err != nil {
		return nil, err
	}
	if !r.empty() {
		return nil, errors.New("unsupported ssh identity")
	}

	pr := sshReader{data: privateBlock}
	check1, err := pr.readUint32()
	if err != nil {
		return nil, err
	}
	check2, err := pr.readUint32()
	if err != nil {
		return nil, err
	}
	if check1 != check2 {
		return nil, errors.New("unsupported encrypted ssh identity")
	}
	keyType, err := pr.readString()
	if err != nil {
		return nil, err
	}

	switch string(keyType) {
	case "ssh-ed25519":
		pub, err := pr.readString()
		if err != nil {
			return nil, err
		}
		priv, err := pr.readString()
		if err != nil {
			return nil, err
		}
		if _, err := pr.readString(); err != nil {
			return nil, err
		}
		if err := pr.checkPadding(); err != nil {
			return nil, err
		}
		if len(pub) != ed25519.PublicKeySize || len(priv) != ed25519.PrivateKeySize {
			return nil, errors.New("unsupported ssh identity")
		}
		wire := pubWire
		if len(wire) == 0 {
			wire = marshalEd25519PublicKey(ed25519.PublicKey(pub))
		}
		curvePub, err := ed25519PublicToCurve25519(pub)
		if err != nil {
			return nil, err
		}
		return &SSHEd25519Identity{
			tag:         sshKeyTag(wire),
			privateKey:  ed25519SeedToCurve25519(priv[:32]),
			publicCurve: curvePub,
			publicWire:  wire,
		}, nil
	case "ssh-rsa":
		n, err := pr.readMPInt()
		if err != nil {
			return nil, err
		}
		e, err := pr.readMPInt()
		if err != nil {
			return nil, err
		}
		d, err := pr.readMPInt()
		if err != nil {
			return nil, err
		}
		if _, err := pr.readMPInt(); err != nil {
			return nil, err
		}
		p, err := pr.readMPInt()
		if err != nil {
			return nil, err
		}
		q, err := pr.readMPInt()
		if err != nil {
			return nil, err
		}
		if _, err := pr.readString(); err != nil {
			return nil, err
		}
		if err := pr.checkPadding(); err != nil {
			return nil, err
		}
		if e.BitLen() > 31 {
			return nil, errors.New("unsupported ssh identity")
		}
		key := &rsa.PrivateKey{
			PublicKey: rsa.PublicKey{
				N: n,
				E: int(e.Int64()),
			},
			D:      d,
			Primes: []*big.Int{p, q},
		}
		if err := key.Validate(); err != nil {
			return nil, err
		}
		key.Precompute()
		wire := pubWire
		if len(wire) == 0 {
			wire = marshalRSAPublicKey(&key.PublicKey)
		}
		return &SSHRSAIdentity{
			tag: sshKeyTag(wire),
			key: key,
		}, nil
	default:
		return nil, errors.New("unsupported ssh identity")
	}
}

func (r *SSHRSARecipient) Wrap(fileKey []byte) (*Stanza, error) {
	body, err := rsa.EncryptOAEP(sha256.New(), rand.Reader, r.key, fileKey, []byte(sshRSALabel))
	if err != nil {
		return nil, err
	}
	return &Stanza{Type: "ssh-rsa", Args: []string{r.tag}, Body: body}, nil
}

func (i *SSHRSAIdentity) Unwrap(stanza *Stanza) ([]byte, bool, error) {
	if stanza.Type != "ssh-rsa" || len(stanza.Args) != 1 {
		return nil, false, nil
	}
	if stanza.Args[0] != i.tag {
		return nil, false, nil
	}
	fileKey, err := rsa.DecryptOAEP(sha256.New(), rand.Reader, i.key, stanza.Body, []byte(sshRSALabel))
	return fileKey, true, err
}

func (i *SSHRSAIdentity) Recipient() (Recipient, error) {
	return &SSHRSARecipient{tag: i.tag, key: &i.key.PublicKey}, nil
}

func (r *SSHEd25519Recipient) Wrap(fileKey []byte) (*Stanza, error) {
	curve := ecdh.X25519()
	eph, err := curve.GenerateKey(rand.Reader)
	if err != nil {
		return nil, err
	}
	shared, err := eph.ECDH(mustX25519PublicKey(r.publicCurve[:]))
	if err != nil {
		return nil, err
	}
	salt := append(append([]byte{}, eph.PublicKey().Bytes()...), r.publicWire...)
	wrapKey := hkdfExpand(shared, salt, []byte(sshED25519Label), chacha20poly1305.KeySize)
	body, err := wrapFileKey(wrapKey, fileKey)
	if err != nil {
		return nil, err
	}
	return &Stanza{
		Type: "ssh-ed25519",
		Args: []string{
			r.tag,
			base64.RawStdEncoding.EncodeToString(eph.PublicKey().Bytes()),
		},
		Body: body,
	}, nil
}

func (i *SSHEd25519Identity) Unwrap(stanza *Stanza) ([]byte, bool, error) {
	if stanza.Type != "ssh-ed25519" || len(stanza.Args) != 2 {
		return nil, false, nil
	}
	if stanza.Args[0] != i.tag {
		return nil, false, nil
	}
	eph, err := base64.RawStdEncoding.DecodeString(stanza.Args[1])
	if err != nil || len(eph) != 32 {
		return nil, true, errors.New("invalid ssh recipient")
	}
	priv, err := ecdh.X25519().NewPrivateKey(i.privateKey[:])
	if err != nil {
		return nil, true, err
	}
	pub, err := ecdh.X25519().NewPublicKey(eph)
	if err != nil {
		return nil, true, err
	}
	shared, err := priv.ECDH(pub)
	if err != nil {
		return nil, true, err
	}
	salt := append(append([]byte{}, eph...), i.publicWire...)
	wrapKey := hkdfExpand(shared, salt, []byte(sshED25519Label), chacha20poly1305.KeySize)
	fileKey, err := unwrapFileKey(wrapKey, stanza.Body)
	return fileKey, true, err
}

func (i *SSHEd25519Identity) Recipient() (Recipient, error) {
	return &SSHEd25519Recipient{
		tag:         i.tag,
		publicWire:  i.publicWire,
		publicCurve: i.publicCurve,
	}, nil
}

func sshKeyTag(wire []byte) string {
	sum := sha256.Sum256(wire)
	return base64.RawStdEncoding.EncodeToString(sum[:4])
}

func parseAuthorizedKeyLine(line string) (*parsedSSHPublic, error) {
	fields := strings.Fields(strings.TrimSpace(line))
	if len(fields) < 2 {
		return nil, errors.New("unsupported ssh recipient")
	}
	algo := fields[0]
	wire, err := base64.StdEncoding.DecodeString(fields[1])
	if err != nil {
		return nil, err
	}
	r := sshReader{data: wire}
	keyType, err := r.readString()
	if err != nil {
		return nil, err
	}
	if string(keyType) != algo {
		return nil, errors.New("unsupported ssh recipient")
	}
	switch algo {
	case "ssh-ed25519":
		pub, err := r.readString()
		if err != nil {
			return nil, err
		}
		if len(pub) != ed25519.PublicKeySize || !r.empty() {
			return nil, errors.New("unsupported ssh recipient")
		}
		return &parsedSSHPublic{algo: algo, wire: wire, ed25519: ed25519.PublicKey(pub)}, nil
	case "ssh-rsa":
		e, err := r.readMPInt()
		if err != nil {
			return nil, err
		}
		n, err := r.readMPInt()
		if err != nil {
			return nil, err
		}
		if !r.empty() || e.BitLen() > 31 {
			return nil, errors.New("unsupported ssh recipient")
		}
		return &parsedSSHPublic{
			algo: algo,
			wire: wire,
			rsa: &rsa.PublicKey{N: n, E: int(e.Int64())},
		}, nil
	default:
		return nil, errors.New("unsupported ssh recipient")
	}
}

func marshalEd25519PublicKey(pub ed25519.PublicKey) []byte {
	var out []byte
	out = appendString(out, []byte("ssh-ed25519"))
	out = appendString(out, pub)
	return out
}

func marshalRSAPublicKey(pub *rsa.PublicKey) []byte {
	var out []byte
	out = appendString(out, []byte("ssh-rsa"))
	out = appendMPInt(out, big.NewInt(int64(pub.E)))
	out = appendMPInt(out, pub.N)
	return out
}

func appendString(dst, s []byte) []byte {
	var lenBuf [4]byte
	binary.BigEndian.PutUint32(lenBuf[:], uint32(len(s)))
	dst = append(dst, lenBuf[:]...)
	return append(dst, s...)
}

func appendMPInt(dst []byte, n *big.Int) []byte {
	if n.Sign() == 0 {
		return appendString(dst, nil)
	}
	b := n.Bytes()
	if b[0]&0x80 != 0 {
		b = append([]byte{0}, b...)
	}
	return appendString(dst, b)
}

func (r *sshReader) readUint32() (uint32, error) {
	if len(r.data) < 4 {
		return 0, io.ErrUnexpectedEOF
	}
	n := binary.BigEndian.Uint32(r.data[:4])
	r.data = r.data[4:]
	return n, nil
}

func (r *sshReader) readString() ([]byte, error) {
	n, err := r.readUint32()
	if err != nil {
		return nil, err
	}
	if uint32(len(r.data)) < n {
		return nil, io.ErrUnexpectedEOF
	}
	out := r.data[:n]
	r.data = r.data[n:]
	return out, nil
}

func (r *sshReader) readMPInt() (*big.Int, error) {
	b, err := r.readString()
	if err != nil {
		return nil, err
	}
	if len(b) == 0 {
		return big.NewInt(0), nil
	}
	if b[0]&0x80 != 0 {
		return nil, errors.New("negative mpint")
	}
	return new(big.Int).SetBytes(b), nil
}

func (r *sshReader) empty() bool {
	return len(r.data) == 0
}

func (r *sshReader) checkPadding() error {
	for i, b := range r.data {
		if b != byte(i+1) {
			return errors.New("invalid ssh padding")
		}
	}
	r.data = nil
	return nil
}

