package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"errors"
)

func scryptKey(password, salt []byte, N, r, p, keyLen int) ([]byte, error) {
	if N <= 1 || (N&(N-1)) != 0 {
		return nil, errors.New("scrypt: N must be > 1 and a power of 2")
	}
	if r <= 0 || p <= 0 {
		return nil, errors.New("scrypt: invalid parameters")
	}
	b := pbkdf2SHA256(password, salt, 1, p*128*r)
	for i := 0; i < p; i++ {
		smix(b[i*128*r:(i+1)*128*r], r, N)
	}
	return pbkdf2SHA256(password, b, 1, keyLen), nil
}

func pbkdf2SHA256(password, salt []byte, iter, keyLen int) []byte {
	hLen := 32
	numBlocks := (keyLen + hLen - 1) / hLen
	var out []byte
	var buf [4]byte
	for block := 1; block <= numBlocks; block++ {
		binary.BigEndian.PutUint32(buf[:], uint32(block))
		u := hmacSHA256(password, salt, buf[:])
		t := append([]byte(nil), u...)
		for i := 1; i < iter; i++ {
			u = hmacSHA256(password, u)
			for j := range t {
				t[j] ^= u[j]
			}
		}
		out = append(out, t...)
	}
	return out[:keyLen]
}

func hmacSHA256(key []byte, parts ...[]byte) []byte {
	h := hmac.New(sha256.New, key)
	for _, part := range parts {
		h.Write(part)
	}
	return h.Sum(nil)
}

func smix(b []byte, r, N int) {
	x := append([]byte(nil), b...)
	v := make([]byte, len(b)*N)
	y := make([]byte, len(b))
	for i := 0; i < N; i++ {
		copy(v[i*len(b):], x)
		blockMix(x, y, r)
		x, y = y, x
	}
	for i := 0; i < N; i++ {
		j := integerify(x, r) & uint64(N-1)
		xorBytes(x, v[int(j)*len(b):int(j+1)*len(b)])
		blockMix(x, y, r)
		x, y = y, x
	}
	copy(b, x)
}

func integerify(b []byte, r int) uint64 {
	offset := (2*r - 1) * 64
	return binary.LittleEndian.Uint64(b[offset:])
}

func blockMix(b, out []byte, r int) {
	x := make([]byte, 64)
	copy(x, b[(2*r-1)*64:(2*r)*64])
	y := make([]byte, len(b))
	for i := 0; i < 2*r; i++ {
		xorBytes(x, b[i*64:(i+1)*64])
		x = salsa208(x)
		copy(y[i*64:], x)
	}
	for i := 0; i < r; i++ {
		copy(out[i*64:(i+1)*64], y[(2*i)*64:(2*i+1)*64])
		copy(out[(i+r)*64:(i+r+1)*64], y[(2*i+1)*64:(2*i+2)*64])
	}
}

func salsa208(in []byte) []byte {
	var x [16]uint32
	for i := 0; i < 16; i++ {
		x[i] = binary.LittleEndian.Uint32(in[i*4:])
	}
	z := x
	for i := 0; i < 4; i++ {
		// Column rounds.
		z[4] ^= rotl(z[0]+z[12], 7)
		z[8] ^= rotl(z[4]+z[0], 9)
		z[12] ^= rotl(z[8]+z[4], 13)
		z[0] ^= rotl(z[12]+z[8], 18)

		z[9] ^= rotl(z[5]+z[1], 7)
		z[13] ^= rotl(z[9]+z[5], 9)
		z[1] ^= rotl(z[13]+z[9], 13)
		z[5] ^= rotl(z[1]+z[13], 18)

		z[14] ^= rotl(z[10]+z[6], 7)
		z[2] ^= rotl(z[14]+z[10], 9)
		z[6] ^= rotl(z[2]+z[14], 13)
		z[10] ^= rotl(z[6]+z[2], 18)

		z[3] ^= rotl(z[15]+z[11], 7)
		z[7] ^= rotl(z[3]+z[15], 9)
		z[11] ^= rotl(z[7]+z[3], 13)
		z[15] ^= rotl(z[11]+z[7], 18)

		// Row rounds.
		z[1] ^= rotl(z[0]+z[3], 7)
		z[2] ^= rotl(z[1]+z[0], 9)
		z[3] ^= rotl(z[2]+z[1], 13)
		z[0] ^= rotl(z[3]+z[2], 18)

		z[6] ^= rotl(z[5]+z[4], 7)
		z[7] ^= rotl(z[6]+z[5], 9)
		z[4] ^= rotl(z[7]+z[6], 13)
		z[5] ^= rotl(z[4]+z[7], 18)

		z[11] ^= rotl(z[10]+z[9], 7)
		z[8] ^= rotl(z[11]+z[10], 9)
		z[9] ^= rotl(z[8]+z[11], 13)
		z[10] ^= rotl(z[9]+z[8], 18)

		z[12] ^= rotl(z[15]+z[14], 7)
		z[13] ^= rotl(z[12]+z[15], 9)
		z[14] ^= rotl(z[13]+z[12], 13)
		z[15] ^= rotl(z[14]+z[13], 18)
	}
	out := make([]byte, 64)
	for i := 0; i < 16; i++ {
		binary.LittleEndian.PutUint32(out[i*4:], z[i]+x[i])
	}
	return out
}

func xorBytes(dst, src []byte) {
	for i := range dst {
		dst[i] ^= src[i]
	}
}

func rotl(v uint32, c uint) uint32 {
	return (v << c) | (v >> (32 - c))
}

