package main

import (
	"bytes"
	"crypto/sha256"
	"fmt"
	"os"
	"testing"

	"golang.org/x/crypto/chacha20"
	"golang.org/x/crypto/chacha20poly1305"
)

func TestProbePassphraseFile(t *testing.T) {
	data, err := os.ReadFile("/workspace/.probe/plain.pass.age")
	if err != nil {
		t.Fatal(err)
	}
	parsed, err := parseAgeFile(data)
	if err != nil {
		t.Fatal(err)
	}
	fileKey, err := unwrapScryptStanza(parsed.Stanzas[0], "million-mind-verify-swarm-cloud-today-field-obscure-orphan-pumpkin")
	if err != nil {
		t.Fatal(err)
	}
	fmt.Printf("fileKey=%x\n", fileKey)
	fmt.Printf("mac-current=%x\n", computeHeaderMAC(fileKey, parsed.HeaderBytes))
	fmt.Printf("mac-file=%x\n", parsed.MAC)
	fmt.Printf("mac-hmac-only=%x\n", hmacSHA256(fileKey, parsed.HeaderBytes))
	candidates := []struct {
		name string
		salt []byte
		info []byte
	}{
		{"hkdf-empty", nil, nil},
		{"hkdf-header", nil, []byte("header")},
		{"hkdf-full-header", nil, []byte("age-encryption.org/v1/header")},
		{"hkdf-age-v1", nil, []byte("age-encryption.org/v1")},
		{"hkdf-intro-header", []byte(fileIntro), []byte("header")},
		{"hkdf-intro-full-header", []byte(fileIntro), []byte("age-encryption.org/v1/header")},
	}
	for _, candidate := range candidates {
		key := hkdfExpand(fileKey, candidate.salt, candidate.info, 32)
		fmt.Printf("%s=%x\n", candidate.name, hmacSHA256(key, parsed.HeaderBytes))
	}
	extra := map[string][]byte{
		"sha256(fileKey)":                      sha256Bytes(fileKey),
		"sha256(headerLabel||fileKey)":        sha256Bytes([]byte("header"), fileKey),
		"sha256(fileKey||headerLabel)":        sha256Bytes(fileKey, []byte("header")),
		"hmac(headerLabel,fileKey)":           hmacSHA256([]byte("header"), fileKey),
		"hmac(fileKey,headerLabel)":           hmacSHA256(fileKey, []byte("header")),
		"hmac(fullHeaderLabel,fileKey)":       hmacSHA256([]byte("age-encryption.org/v1/header"), fileKey),
		"hmac(fileKey,fullHeaderLabel)":       hmacSHA256(fileKey, []byte("age-encryption.org/v1/header")),
		"hmac(intro,fileKey)":                 hmacSHA256([]byte(fileIntro), fileKey),
		"hmac(fileKey,intro)":                 hmacSHA256(fileKey, []byte(fileIntro)),
		"sha256(fullHeaderLabel||fileKey)":    sha256Bytes([]byte("age-encryption.org/v1/header"), fileKey),
		"sha256(fileKey||fullHeaderLabel)":    sha256Bytes(fileKey, []byte("age-encryption.org/v1/header")),
	}
	for name, key := range extra {
		fmt.Printf("%s=%x\n", name, hmacSHA256(key, parsed.HeaderBytes))
	}
	key := hkdfExpand(fileKey, nil, []byte("age-encryption.org/v1/header"), 32)
	fmt.Printf("variant-no-intro=%x\n", hmacSHA256(key, parsed.HeaderBytes[len(fileIntro):]))
	fmt.Printf("variant-no-final-nl=%x\n", hmacSHA256(key, parsed.HeaderBytes[:len(parsed.HeaderBytes)-1]))
	fmt.Printf("variant-plus-delim=%x\n", hmacSHA256(key, append(append([]byte{}, parsed.HeaderBytes...), []byte("--- ")...)))
	fmt.Printf("hkdf-full-header-16=%x\n", hmacSHA256(hkdfExpand(fileKey, nil, []byte("age-encryption.org/v1/header"), 16), parsed.HeaderBytes))
	fmt.Printf("hkdf-header-16=%x\n", hmacSHA256(hkdfExpand(fileKey, nil, []byte("header"), 16), parsed.HeaderBytes))
	fmt.Printf("sha256(fileKey||header)=%x\n", sha256Bytes(fileKey, parsed.HeaderBytes))
	fmt.Printf("sha256(header||fileKey)=%x\n", sha256Bytes(parsed.HeaderBytes, fileKey))
	fmt.Printf("sha256(fullLabel||fileKey||header)=%x\n", sha256Bytes([]byte("age-encryption.org/v1/header"), fileKey, parsed.HeaderBytes))
	fmt.Printf("sha256(fileKey||fullLabel||header)=%x\n", sha256Bytes(fileKey, []byte("age-encryption.org/v1/header"), parsed.HeaderBytes))
	for _, payloadKey := range [][]byte{
		hkdfExpand(fileKey, nil, []byte("payload"), 32),
		hkdfExpand(fileKey, nil, []byte("age-encryption.org/v1/payload"), 32),
		hkdfExpand(fileKey, nil, nil, 32),
		hkdfExpand(fileKey, []byte(fileIntro), []byte("payload"), 32),
		hkdfExpand(fileKey, []byte(fileIntro), []byte("age-encryption.org/v1/payload"), 32),
		hkdfExpand(fileKey, parsed.HeaderBytes, []byte("payload"), 32),
		hkdfExpand(fileKey, parsed.HeaderBytes, []byte("age-encryption.org/v1/payload"), 32),
		hmacSHA256(fileKey, []byte("payload")),
		hmacSHA256([]byte("payload"), fileKey),
		hmacSHA256(fileKey, []byte("age-encryption.org/v1/payload")),
		hmacSHA256([]byte("age-encryption.org/v1/payload"), fileKey),
		append(append([]byte{}, fileKey...), fileKey...),
		sha256Bytes(fileKey),
		mustHChaCha(append(append([]byte{}, fileKey...), make([]byte, 16)...)),
		mustHChaCha(append(append([]byte{}, make([]byte, 16)...), fileKey...)),
		mustHChaCha(sha256Bytes(fileKey)),
	} {
		for _, nonce := range nonceCandidates() {
			pt, err := decryptPayloadWithKey(payloadKey, parsed.Payload, nonce)
			if err == nil {
				fmt.Printf("payload-key=%x nonce=%x pt=%q\n", payloadKey, nonce, pt)
			}
		}
		for _, nonce := range xNonceCandidates() {
			pt, err := decryptPayloadWithXKey(payloadKey, parsed.Payload, nonce)
			if err == nil {
				fmt.Printf("xpayload-key=%x nonce=%x pt=%q\n", payloadKey, nonce, pt)
			}
		}
	}
	searchMACs(fileKey, parsed)
}

func sha256Bytes(parts ...[]byte) []byte {
	h := sha256.New()
	for _, part := range parts {
		h.Write(part)
	}
	return h.Sum(nil)
}

func decryptPayloadWithKey(key, payload, nonce []byte) ([]byte, error) {
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	chunk := payload
	return aead.Open(nil, nonce, chunk, nil)
}

func nonceCandidates() [][]byte {
	var out [][]byte
	out = append(out, make([]byte, 12))
	for i := 0; i < 12; i++ {
		for _, v := range []byte{1, 0x80, 0xff} {
			n := make([]byte, 12)
			n[i] = v
			out = append(out, n)
		}
	}
	return out
}

func xNonceCandidates() [][]byte {
	var out [][]byte
	out = append(out, make([]byte, 24))
	for i := 0; i < 24; i++ {
		for _, v := range []byte{1, 0x80, 0xff} {
			n := make([]byte, 24)
			n[i] = v
			out = append(out, n)
		}
	}
	return out
}

func decryptPayloadWithXKey(key, payload, nonce []byte) ([]byte, error) {
	aead, err := chacha20poly1305.NewX(key)
	if err != nil {
		return nil, err
	}
	return aead.Open(nil, nonce, payload, nil)
}

func mustHChaCha(key []byte) []byte {
	out, err := chacha20.HChaCha20(key, make([]byte, 16))
	if err != nil {
		panic(err)
	}
	return out
}

func searchMACs(fileKey []byte, parsed *parsedAgeFile) {
	labels := [][]byte{
		nil,
		[]byte("header"),
		[]byte("age-encryption.org/v1/header"),
		[]byte("age-encryption.org/v1"),
		[]byte("mac"),
	}
	headers := map[string][]byte{
		"header":            parsed.HeaderBytes,
		"no-intro":          parsed.HeaderBytes[len(fileIntro):],
		"no-final":          parsed.HeaderBytes[:len(parsed.HeaderBytes)-1],
		"no-intro-no-final": parsed.HeaderBytes[len(fileIntro) : len(parsed.HeaderBytes)-1],
	}
	salts := map[string][]byte{
		"nil":      nil,
		"intro":    []byte(fileIntro),
		"header":   parsed.HeaderBytes,
		"no-intro": parsed.HeaderBytes[len(fileIntro):],
	}
	type candidate struct {
		name string
		key  []byte
	}
	var candidates []candidate
	candidates = append(candidates,
		candidate{"raw", fileKey},
		candidate{"sha256(fileKey)", sha256Bytes(fileKey)},
	)
	for _, label := range labels {
		if label == nil {
			continue
		}
		candidates = append(candidates,
			candidate{fmt.Sprintf("sha256(label:%q||fileKey)", label), sha256Bytes(label, fileKey)},
			candidate{fmt.Sprintf("sha256(fileKey||label:%q)", label), sha256Bytes(fileKey, label)},
			candidate{fmt.Sprintf("hmac(fileKey,label:%q)", label), hmacSHA256(fileKey, label)},
			candidate{fmt.Sprintf("hmac(label:%q,fileKey)", label), hmacSHA256(label, fileKey)},
		)
	}
	for saltName, salt := range salts {
		for _, label := range labels {
			for _, n := range []int{16, 32} {
				candidates = append(candidates, candidate{
					name: fmt.Sprintf("hkdf(salt=%s,info=%q,n=%d)", saltName, label, n),
					key:  hkdfExpand(fileKey, salt, label, n),
				})
			}
		}
	}
	found := 0
	for _, c := range candidates {
		for headerName, header := range headers {
			if bytes.Equal(parsed.MAC, hmacSHA256(c.key, header)) {
				fmt.Printf("MATCH-HMAC key=%s header=%s\n", c.name, headerName)
				found++
			}
			if bytes.Equal(parsed.MAC, sha256Bytes(c.key, header)) {
				fmt.Printf("MATCH-SHA key||header key=%s header=%s\n", c.name, headerName)
				found++
			}
			if bytes.Equal(parsed.MAC, sha256Bytes(header, c.key)) {
				fmt.Printf("MATCH-SHA header||key key=%s header=%s\n", c.name, headerName)
				found++
			}
		}
	}
	fmt.Printf("mac-search-found=%d\n", found)
}
